-- SQL DDL for ClickHouse, generated by ormbridge.

CREATE TABLE account (
  id UUID DEFAULT generateUUIDv4(),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  deleted_at Nullable(DateTime64(3)),
  email String,
  balance Decimal(10, 2),
  score Nullable(Float64),
  avatar Nullable(String) COMMENT 'binary data',
  payload Nullable(String) COMMENT 'JSON document',
  labels Array(String),
  ttl Nullable(Int64) COMMENT 'duration in microseconds',
  ip Nullable(IPv6),
  homepage_url Nullable(String),
  born Nullable(Date32),
  alarm Nullable(String) COMMENT 'time of day (HH:MM:SS)',
  status Enum8('draft' = 1, 'live' = 2) DEFAULT 'draft',
  note String DEFAULT 'it''s; fine',
  INDEX account_deleted_at_idx deleted_at TYPE minmax GRANULARITY 4,
  INDEX account_email_status_idx (email, status) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE session (
  id UUID DEFAULT generateUUIDv4(),
  token Nullable(UUID) DEFAULT generateUUIDv4(),
  deleted_at Nullable(DateTime64(3)),
  opened_at DateTime64(3) DEFAULT now64(3),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  account_id Nullable(UUID),
  INDEX session_account_id_opened_at_idx (account_id, opened_at) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE `group` (
  id UUID DEFAULT generateUUIDv4(),
  name String,
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE membership (
  role Enum8('owner' = 1, 'member' = 2),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  account_id UUID,
  group_id UUID
)
ENGINE = MergeTree()
ORDER BY (account_id, group_id)
PRIMARY KEY (account_id, group_id);

CREATE TABLE profile (
  id UUID DEFAULT generateUUIDv4(),
  bio Nullable(String),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  owner_account_id UUID
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE legacy_order (
  order_no Int32,
  kind String,
  http_code Int32,
  first_name Nullable(String),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  acct Nullable(UUID)
)
ENGINE = MergeTree()
ORDER BY (order_no)
PRIMARY KEY (order_no);

CREATE TABLE group_friend (
  id UUID DEFAULT generateUUIDv4(),
  from_group_id UUID,
  to_group_id UUID,
  INDEX group_friend_from_group_id_to_group_id_idx (from_group_id, to_group_id) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id)
COMMENT 'many-to-many join table';
